-- Top-level entity for the prototype module.
--
-- Generated by bust. A thin, fixed wrapper around the wishbone endpoint so the
-- module has one stable entity to instantiate. There is no user-editable region;
-- connect your logic to the to_hw/from_hw records.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

use work.prototype_regfile_pkg.all;

entity prototype is
  generic (
    G_BASE_ADDRESS       : unsigned(31 downto 0) := 32x"0";
    G_CHECK_BASE_ADDRESS : boolean := true
  );
  port (
    clk_i   : in  std_logic;
    rst_i   : in  std_logic;

    cyc_i   : in  std_logic;
    stb_i   : in  std_logic;
    we_i    : in  std_logic;
    adr_i   : in  std_logic_vector(31 downto 0);
    dat_i   : in  std_logic_vector(31 downto 0);
    dat_o   : out std_logic_vector(31 downto 0);
    ack_o   : out std_logic;
    err_o   : out std_logic;
    to_hw    : out t_prototype_to_hw;
    from_hw  : in  t_prototype_from_hw
  );
end entity prototype;

architecture rtl of prototype is
begin

  i_endpoint : entity work.prototype_wishbone_endpoint
    generic map (
      G_BASE_ADDRESS       => G_BASE_ADDRESS,
      G_CHECK_BASE_ADDRESS => G_CHECK_BASE_ADDRESS)
    port map (
      clk_i   => clk_i,
      rst_i   => rst_i,
      cyc_i   => cyc_i,
      stb_i   => stb_i,
      we_i    => we_i,
      adr_i   => adr_i,
      dat_i   => dat_i,
      dat_o   => dat_o,
      ack_o   => ack_o,
      err_o   => err_o,
      to_hw    => to_hw,
      from_hw  => from_hw
    );

end architecture rtl;
